// Gera o anúncio de DIVULGAÇÃO DOS GRUPOS para cada rede, a partir das
// ofertas reais do site. Objetivo declarado pelo Daniel: "preciso que as
// pessoas entrem no grupo e comprem pelo meu link de afiliado".
//
// Instagram/TikTok não têm API pública que aceite publicação sem um app de
// negócios aprovado — então este workflow entrega o post PRONTO no chat do
// Daniel (texto + foto + link), para publicar em 10 segundos. O que dá pra
// automatizar de ponta a ponta (Telegram) já sai publicado.
const CONFIG = {
  admin_chat_id: '',                       // preencha (mesmo do workflow 01)
  canal: '@ofertaseletronics',
  grupo_whatsapp: 'https://chat.whatsapp.com/JyJ9uLoZdE5LboH9GjAooC',
  grupo_telegram: 'https://t.me/ofertaseletronics',
  ponte: 'https://bot-ofertas.github.io/grupos/',
};

const REDES = ['instagram', 'tiktok', 'facebook'];
const store = $getWorkflowStaticData('global');
store.rodada = ((store.rodada || 0) + 1) % REDES.length;
const rede = REDES[store.rodada];

const produtos = ($json.products || [])
  .filter(p => p.link && p.foto && (p.desconto_pct || 0) >= 25)
  .sort((a, b) => (b.desconto_pct || 0) - (a.desconto_pct || 0))
  .slice(0, 3);

const brl = v => 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',');
const utm = (url, conteudo) => `${url}${url.includes('?') ? '&' : '?'}utm_source=${rede}` +
                               `&utm_medium=social&utm_campaign=grupo_ofertas&utm_content=${conteudo}`;

const HASHTAGS = {
  instagram: '#ofertas #promoção #achadinhos #descontos #mercadolivre #tecnologia',
  tiktok: '#ofertas #achadinhos #promocao #tecnologia #fyp',
  facebook: '#ofertas #promoções #descontos',
};

let corpo;
if (produtos.length) {
  corpo = `🔥 ${produtos.length} achados de hoje:\n\n` + produtos.map((p, i) =>
    `${i + 1}. ${p.titulo.slice(0, 60)}\n   ${brl(p.preco)}` +
    (p.desconto_pct ? ` (${Math.round(p.desconto_pct)}% OFF)` : '')
  ).join('\n');
} else {
  corpo = '📦 Ofertas de eletrônicos, celulares e informática garimpadas todo dia.\n' +
          '✅ Só promoção real: o preço é conferido contra o histórico antes de ir pro grupo.';
}

const texto =
  `${corpo}\n\n` +
  `Quer receber ofertas assim todos os dias?\n` +
  `📢 Telegram: ${utm(CONFIG.grupo_telegram, 'post_social')}\n` +
  `📲 WhatsApp: ${utm(CONFIG.grupo_whatsapp, 'post_social')}\n` +
  `🔗 Ou entre por aqui: ${utm(CONFIG.ponte, 'post_social')}\n\n` +
  (HASHTAGS[rede] || '');

const aviso =
  `📣 <b>Post pronto para ${rede.toUpperCase()}</b>\n` +
  `Copie o texto abaixo e publique (foto sugerida no próximo envio):\n\n` +
  // Escapar `&` TAMBEM, e antes dos sinais: o proprio texto carrega URLs
  // com `&utm_medium=...`, entao a versao que so trocava < e > fazia o
  // Telegram recusar TODO aviso deste workflow com "can't parse entities".
  `<code>${String(texto).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')}</code>`;

return [{ json: { rede, texto, aviso, chat_id: CONFIG.admin_chat_id,
                  foto: produtos[0]?.foto || '', tem_foto: !!produtos[0]?.foto } }];
